  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Baclofen, a small polar drug containing a chlorophenyl group, has an absolute oral bioavailability of 81.2% in healthy volunteers, directly demonstrating that this structural class can achieve high systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Doravirine has an oral bioavailability of 64% after a 100-mg tablet, and this is not significantly affected by food, supporting high oral bioavailability for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Alprazolam, a closely related heteroaromatic CNS drug, has an absolute oral bioavailability of 84% in humans, indicating efficient absorption and limited first-pass loss for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Trazodone showed an absolute systemic availability of 82% in young men after oral dosing, providing another direct human absolute-bioavailability measurement supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Brotizolam, a triazolothienodiazepine with a chlorophenyl group, has an absolute oral bioavailability of 70% in young healthy volunteers, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence, with very high assay-transfer scores, reports oral bioavailability values well above the 20% threshold (44-92%), including direct absolute-F human studies. Food effects reported for some analogs do not reduce F below the threshold, and doravirine is explicitly unaffected by food. Therefore the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "No dedicated fed-state pharmacokinetic study is available for the query itself.",
    "Extrapolation relies on close structural analogs rather than the query compound."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

